//Extends: Nueva Clase Hija de Modulo
public class ModuloVuelo extends Modulo {

    protected boolean camara;
    protected int datosCiclo;
    protected int energiaConsumo;
    protected int ciclosVuelo;

//Creación del vacío, default
    public ModuloVuelo() {
		//Super traerá los datos que necesito de Modulo, ,luego agrego solo los nuevos
        super();
        camara = false;
        datosCiclo = 0;
        energiaConsumo = 0;
        ciclosVuelo = 0;
    }

//Para el Nuevo ModuloVuelo, sí necesito todos los datos para crearlo, pero usaré un Super para importarlos.
    public ModuloVuelo(String id, String nombre, int salud, boolean activo, int clase, float costo, boolean camara, int datosCiclo, int energiaConsumo, int ciclosVuelo) {
		//El super en cuestión
        super(id, nombre, salud, activo, clase, costo);
		//Los datos nuevos
        this.camara = camara;
        this.datosCiclo = datosCiclo;
        this.energiaConsumo = energiaConsumo;
        this.ciclosVuelo = ciclosVuelo;
    }

//Setters y getters: rutina a estas alturas
    public void setCamara(boolean newCamara) {
        camara = newCamara;
    }

    public boolean getCamara() {
        return camara;
    }


    public void setDatosCiclo(int newDatosCiclo) {
        datosCiclo = newDatosCiclo;
    }

    public int getDatosCiclo() {
        return datosCiclo;
    }


    public void setEnergiaConsumo(int newEnergiaConsumo) {
        energiaConsumo = newEnergiaConsumo;
    }

    public int getEnergiaConsumo() {
        return energiaConsumo;
    }


    public void setCiclosVuelo(int newCiclosVuelo) {
        ciclosVuelo = newCiclosVuelo;
    }

    public int getCiclosVuelo() {
        return ciclosVuelo;
    }

//Override del ProcesoCiclo. Para ese necesito los datos de la Mision (Recursos)
    @Override
    public void procesoCiclo(Mision mision) {


//Sí, pedí ayuda para esto.

        if (!activo) {
			//Obvio, solo si es activo el modulo se activa, duh
            System.out.println(nombre + " no operó porque está inactivo.");

        } else if (mision.getEnergiaDisponible() < energiaConsumo) {
			//Si no hay energia suficiente, no funciona
            System.out.println(nombre + " no operó por energía insuficiente.");

        } else {
			//Tiene energ+ia Y está activo, entonces...

			//Altero la energia
            mision.setEnergiaDisponible(mision.getEnergiaDisponible() - energiaConsumo);

			//Altero los datos en orbita
            mision.setDatosOrbita(mision.getDatosOrbita() + datosCiclo);

            //Aumento en 1 los ciclos de este modulo
			ciclosVuelo++;

			//¿Cuántos datos fueron recolectados?
            System.out.println(nombre + " recolectó " + datosCiclo + " MB.");
        }
    }


    @Override
	//He aqui el override que hablaba. Acá, mostraré también los datos nuevos y los datos previos.
    public void mostrarCaracteristicas() {

        if (camara) {
            System.out.println("Instrumento: Cámara");
        } else {
            System.out.println("Instrumento: Sensor");
        }

        System.out.println("Datos por ciclo: " + datosCiclo + " MB");
        System.out.println("Consumo de energía: " + energiaConsumo);
        System.out.println("Ciclos de vuelo: " + ciclosVuelo);
    }
}